@startuml

class Course {
  + name : string
}

class Edition {
  + number_of_participants : int
}

class Lesson {
  + date : date
  + startTime : time
  + duration : int
}

class Resource {
  + name : string
}

abstract class Teacher {
  + name : string
}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class Room {}

Course "1" -- "*" Edition : is offered in
Edition "1" *-- "*" Lesson : is organized into
Lesson "*" -- "*" Teacher : is given by
Course "1" -- "1" InternalTeacher : has responsible
Teacher "1..*" -- "0..*" Course : is assigned to
Lesson "*" -- "1" Room : has assigned
Lesson "*" -- "*" Resource : may require

Edition "1" -- "*" MasterStudent : has participants
Edition "1" -- "*" ExternalAuditor : has participants

@enduml

